        else
            go = self._uiTeamMemberNodeScr:FillCardBase(self._data, 1, function()
                if self._cardCb then
                    self._cardCb()
                end
            end)
        end

        local FishingUtils = import('Game.UI.Fishing.FishingUtils')
        local isCanFish = FishingUtils.IsCardGetAndCanFishing(self._data.cardId)
