        allChildGrayGraphics:MarkGray(not isCanFish)
        local grayGraphics = go.transform:Find("HeadImage"):GetComponent(typeof(UIGrayGraphics))
        grayGraphics:MarkGray(not isCanFish)
    end

    self:RefreshChooseStatu(false)
end

