---@param cardDojo CardDojo
---@param cb fun():void
---@param selectMap table<string, string> @ key：卡牌id，value：位置
---@param checkSame boolean | nil @ 是否需要检查卡牌重复
function UIFightChooseCardsCardCellNode:RefreshCustom(cardDojo, cb, selectMap, checkSame)
    if not cardDojo then
        return
    end
    self._cardCb = cb
    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:ShowHpEnergy(false)
    end

    CfUtils.SetActive(self.Mask, true)
    CfUtils.SetActive(self.CaseBg, false)
    CfUtils.SetUISwitchImage(self.CaseBg, 1)
    CfUtils.SetUISwitchText(self.CaseText, 1)
    CfUtils.SetActive(self.ImgBlack, false)
    CfUtils.SetActive(self.ImgGlow, false)
    
    self:RefreshImgSelectStatu(false)
    self:RefreshChooseStatu(false)
    self:RefreshBaseData(cardDojo)

    local isSelected = false
    local currentPos = 0
    if selectMap then
        currentPos = checkInt(selectMap[tostring(cardDojo.cardId)])
        isSelected = currentPos > 0
    end
    self:RefreshChooseStatu(isSelected)
    self:RefreshCurPos(currentPos)

    -- 相同卡牌不允许上阵
    if not isSelected and checkSame then
        for cardId, _ in pairs(selectMap) do
            local vo1 = CardConfMgr:GetInstance():GetCardByRefId(cardId)
            local vo2 = CardConfMgr:GetInstance():GetCardByRefId(self._data.cardId)
            if checkNumber(vo1.characterId) == checkNumber(vo2.characterId) then
                CfUtils.SetActive(self.CaseBg, true)
                break
            end
        end
    end
end


function UIFightChooseCardsCardCellNode:Refresh(data, cb, fishQueueId, questId, teamIndex)
    if not data then
        return
    end
    self:RefreshImgSelectStatu(false)

    self._data = data
    self._cardCb = cb
    self._curFishQueueId = checkNumber(fishQueueId)
    self._curQuestId = checkNumber(questId)
    self._teamIndex = teamIndex
    local questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)

    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:Refresh(data, 1, function()
            if self._cardCb then
                if questType == Constants.IDType.ActivityCrisis then
                    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
                    local isLimit = QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Limit, self._data.cardId)
                    if isLimit then
                        GameUtils.Toast(localize("无法上阵受限战斗员"))
                        return
                    end
                    self._cardCb()
                else
                    self._cardCb()
                end
            end
        end)
    end

    CfUtils.SetActive(self.Mask, true)
    CfUtils.SetActive(self.CaseBg, false)
    CfUtils.SetUISwitchImage(self.CaseBg, 1)
    CfUtils.SetUISwitchText(self.CaseText, 1)
    CfUtils.SetActive(self.ImgBlack, false)
    CfUtils.SetActive(self.ImgGlow, false)

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if vo then
        local isLimitCard = GameUtils.IsLimitCard(self._curQuestId,self._data.id, self._teamIndex)
        --有上阵条件
        if checkNumber(vo.roleRestrictions) > 0 then
            local isLimit = QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Limit, self._data.cardId)
            if isLimit or isLimitCard then
                CfUtils.SetActive(self.CaseBg, true)
                CfUtils.SetActive(self.ImgBlack, true)
                CfUtils.SetUISwitchImage(self.CaseBg, 3)
                CfUtils.SetUISwitchText(self.CaseText, 3)
            end
            local isMust = QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Must, self._data.cardId)
            if isMust then
                CfUtils.SetActive(self.CaseBg, true)
                CfUtils.SetActive(self.ImgGlow, true)
                CfUtils.SetUISwitchImage(self.CaseBg, 2)
                CfUtils.SetUISwitchText(self.CaseText, 2)
            end
        else
            if isLimitCard then
                CfUtils.SetActive(self.CaseBg, true)
                CfUtils.SetActive(self.ImgBlack, true)
                CfUtils.SetUISwitchImage(self.CaseBg, 3)
                CfUtils.SetUISwitchText(self.CaseText, 3)
            end
        end 
    end

    local key = teamComponent:GetTeamCardKey(teamComponent:GetBufferTeam(), self._data.id)
    --如果已经再队伍中
    if key then
        self:RefreshChooseStatu(true)
        self:RefreshCurPos(key)


        local memberData = teamComponent:GetTeamCardData(teamComponent:GetBufferTeam(), self._data.id)
        if not memberData or checkNumber(memberData.type) ~= Constants.TeamMemberType.QuestLockHelperCard then
            KTool.SetActive(self.BtnDelete, true)
        else
            KTool.SetActive(self.BtnDelete, false)
        end
    else
        self:RefreshChooseStatu(false)

        local isCanJoinTeam = teamComponent:IsCanJoinTeam(teamComponent:GetBufferTeam(), data)
        KTool.SetActive(self.BtnDelete, false)

        if not isCanJoinTeam then
            CfUtils.SetActive(self.ImgGlow, false)
            CfUtils.SetActive(self.ImgBlack, true)
            CfUtils.SetUISwitchImage(self.CaseBg, 1)
            CfUtils.SetUISwitchText(self.CaseText, 1)
            KTool.SetActive(self.CaseBg, true)
        end
    end

    if data.usable and data.usable == 0 then -- 额外的ban人逻辑
        CfUtils.SetActive(self.CaseBg, true)
        CfUtils.SetActive(self.ImgBlack, true)
        CfUtils.SetUISwitchImage(self.CaseBg, 3)
        CfUtils.SetUISwitchText(self.CaseText, 3)
    end
    

    local isHideFetters = QuestConfMgr:GetInstance():IsHideFetters(self._curQuestId, questType)
    if not isHideFetters then
        local fettersKey
        if questType == Constants.IDType.QuestChaoticRecall then
            fettersKey = teamComponent:IsCardFetterInAllTeam(questId, self._data.id)
        else
            fettersKey = teamComponent:GetTeamFettersCardKey(teamComponent:GetBufferTeam(), self._data.cardId)
        end
        if fettersKey then
            CfUtils.SetActive(self.CaseBg, true)
            CfUtils.FillText(self.CaseText, localize("已被使用.."))
        end
    end

    self:FillRobot()
end

