--绘制钓鱼挂机
function UIFightChooseCardsCardCellNode:FillFishHangUpInfo()
    if not self._data then
        return
    end

    local dojo = FishingUtils.GetCardFishHangUpData(self._data.id)
    --如果该卡在队列中
    if dojo then
        if checkNumber(dojo.teamId) ~= self._curFishQueueId then
            --self._cardCb = nil
            KTool.SetActive(self.TeamIndex, true)
            CfUtils.FillText(self.TeamPositionNum, string.format("Team-%d-", dojo.teamId))
    
            KTool.SetActive(self.Dead, true)
        else
            KTool.SetActive(self.Dead, false)
            KTool.SetActive(self.TeamIndex, false)
        end
    else
        KTool.SetActive(self.Dead, false)
        KTool.SetActive(self.TeamIndex, false)
    end

    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:FillHpEnergy({
            hpPercent = FishingUtils.GetFishCardEnergyNum(self._data.id) / FishingUtils.GetFishCardMaxEnergyNum(self._data.cardId)
        })
    end
end

--绘制委托
function UIFightChooseCardsCardCellNode:FillEntrustInfo()
    if not self._data then
        return
    end

    local t = teamComponent:GetCardEntrustData(self._data.id)
    --如果该卡在队列中
    if t then
        KTool.SetActive(self.TeamIndex, true)
        CfUtils.FillText(self.TeamPositionNum, string.format("Team-%d-", t.id))

        --如果该卡牌再委托队列进行中
        if teamComponent:IsCardEntrusting(self._data.id) then
            self._cardCb = nil
            KTool.SetActive(self.Dead, true)
        else
            KTool.SetActive(self.Dead, false)
        end
    else
        KTool.SetActive(self.Dead, false)
        KTool.SetActive(self.TeamIndex, false)
    end
end

--绘制迷宫
function UIFightChooseCardsCardCellNode:FillMazeInfo()
    if not self._data then
        return
    end

    --没血不能点
    if checkNumber(self._data.hpPercent) <= 0 then
        self._cardCb = nil
    end
    KTool.SetActive(self.MazeRoleBg, self._data.isAssistant == Constants.MazeRole.AssistRole)

    --迷宫支援角色背景展示
    if self._data.isAssistant == Constants.MazeRole.AssistRole then
        CfUtils.FillText(self.MazeRoleText, localize("支援"))
    end
    self:FillHpEnergInfo(self._data)
end

--绘制海外夜巡迷宫
function UIFightChooseCardsCardCellNode:FillPatrolMazeInfo(patrolMaze)
    if not self._data then
        return
    end

    ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
    local areaDojo     = patrolMaze.areaDojo
    local mazeCardDojo = areaDojo:GetMazeCard(self._data.id)

    --没血不能点
    if checkNumber(mazeCardDojo.hpPercent) <= 0 then
        self._cardCb = nil
    end
    CfUtils.SetActive(self.MazeRoleBg, mazeCardDojo.isAssist)

    self:FillHpEnergInfo({
        hpPercent = mazeCardDojo.hpPercent,
        energy    = mazeCardDojo.energy,
    })
end

