    end

    --local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(levelId, self._data.id)

    KTool.SetActive(self.TeamIndex, false)
    KTool.SetActive(self.Dead, false)
    --if isInTeam then
    --    if checkNumber(teamIndex) ~= checkNumber(curTeamIndex) then
    --        KTool.SetActive(self.TeamIndex, true)
    --        KTool.SetActive(self.Dead, true)
    --        CfUtils.FillText(self.TeamPositionNum, string.format("Team-%d-", checkNumber(teamIndex)))
    --        self._cardCb = nil
    --    end
    --end
    self:FillUpInfo(upData)
end

--绘制天赋副本
function UIFightChooseCardsCardCellNode:FillTalentInfo(upData)
    if not self._data then
        return
    end
    local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
    local hpEnergyData = talentQuestComponent:GetCardHpEngyData(self._data.id)

    if checkNumber(hpEnergyData.hpPercent) <= 0 then
        self._cardCb = nil
    end  
    self:FillHpEnergInfo(hpEnergyData)
    self:FillUpInfo(upData)
end

--绘制血量信息
function UIFightChooseCardsCardCellNode:FillHpEnergInfo(hpEnergyData)
    if not hpEnergyData then
        return
    end

    KTool.SetActive(self.Dead, checkNumber(hpEnergyData.hpPercent) <= 0)

    local maxEnergyNum = 0
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(self._data.cardId)
    if cardVo then
        maxEnergyNum = checkNumber(cardVo.maxSp)
    end

    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:FillHpEnergy(hpEnergyData, maxEnergyNum)
    end
end

--绘制up图片
function UIFightChooseCardsCardCellNode:FillUpInfo(upData)
    local isUp = QuestConfMgr:GetInstance():IsCardUp(self._data.cardId, upData)
    -- KTool.SetActive(self.BuffUp, isUp)
    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:FillUpInfo(isUp)
    end
end

function UIFightChooseCardsCardCellNode:RefreshEnergy()
    if  isNull(self._data) then
        return
    end
    if not FishingUtils.IsCardCanFishing(self._data.cardId) then
        return
    end

    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:FillHpEnergy({
            hpPercent = FishingUtils.GetFishCardEnergyNum(self._data.id) / FishingUtils.GetFishCardMaxEnergyNum(self._data.cardId)
        })
    end

    KTool.SetActive(self.fish_recovery, FishingUtils.IsCardGetAndCanFishing(self._data.cardId) and FishingUtils.GetFishCardEnergyNum(self._data.id) ~= FishingUtils.GetFishCardMaxEnergyNum(self._data.cardId))
end

--机器人
function UIFightChooseCardsCardCellNode:FillRobot()
    --没数据
    if not self._data then
        KTool.SetActive(self.Robot, false)
    else
        local isRobot = checkNumber(self._data.isAssistant) == Constants.MazeRole.AssistRole
        KTool.SetActive(self.Robot, isRobot)
        if isRobot then
        end
    end
end

function UIFightChooseCardsCardCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

---回对象池初始化状态
---按照prefab对象显隐情况重置
function UIFightChooseCardsCardCellNode:OnReset()
    self._data = nil
    self._cardCb = nil
    self._delCb = nil

    self._curFishQueueId = nil
    self._curQuestId = nil

    -- KTool.SetActive(self.BuffUp, false)
    if self._uiTeamMemberNodeScr then
        self._uiTeamMemberNodeScr:FillUpInfo(false)
    end
    KTool.SetActive(self.CatHouse, false)
    KTool.SetActive(self.Choose, false)
    KTool.SetActive(self.ChoosePosText, false)
    KTool.SetActive(self.BtnDelete, false)
    KTool.SetActive(self.Current, false)
    KTool.SetActive(self.Dead, false)
    KTool.SetActive(self.fish_recovery, false)
    KTool.SetActive(self.ImgSelect, false)
    KTool.SetActive(self.Mask, false)
    -- CfUtils.SetActive(self.ImgBlack, false)
    CfUtils.SetActive(self.ImgGlow, false)
    -- CfUtils.SetActive(self.CaseBg, false)
    KTool.SetActive(self.MazeRoleBg, false)
    KTool.SetActive(self.Robot, false)
    KTool.SetActive(self.TeamIndex, false)

    if isNotNull(self._uiTeamMemberNodeScr) then
        self._uiTeamMemberNodeScr:SetImgFetterShowState(false)
    end

    ---判断是否存在变灰组件，存在则确保所有图像恢复
    local allChildGrayGraphics = KTool.GetComponent(self.controller.gameObject, typeof(UIAllChildGrayGraphics))
    if not isNull(allChildGrayGraphics) then 
        allChildGrayGraphics:MarkGray(false)
    end 
end 

return UIFightChooseCardsCardCellNode